SELECT COUNT(*) AS rentable_listings
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

select max(agreed_price) as highest_sale_price
from nlq.my_deals
where my_role = 'seller' and status = 'completed';

SELECT COUNT(*) AS deactivated_count
FROM nlq.students
WHERE account_status = 'deactivated';

SELECT COUNT(*) AS moderator_count
FROM nlq.students
WHERE is_moderator = true;

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL;

select count(*) as conversations_no_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (r.resolved_at - r.filed_at))/86400)::numeric, 2) AS avg_days_to_resolve
FROM nlq.reports r
WHERE r.status = 'resolved';

SELECT COUNT(*) AS listings_with_no_photos
FROM nlq.listings_all
WHERE photo_count = 0;
